      "Là vitamin tan trong dầu. - Vitamin D nội sinh được tổng hợp ở da là vitamin D3. Chất này được protein vận chuyển vào máu. - Vitamin D ngoại sinh được hấp thu ở phần trên ruột non với sự tham gia của muối mật. Vì vậy các rối loạn về bài tiết mật sẽ ảnh hưởng đến hấp thu vitamin D. Vitamin D này vào máu qua hệ thống bạch huyết. - Trong máu vitamin D đươci gắn vào protein và vận chuyển tới gan (một globulin), rồi trải qua 1 giai đoạn chuyển hóa - Gđ 1: xảy ra tại microsom của tế bào gan + Cholecalciferol chuyển thành 25(OH)D3 nhờ men 25-hydroxylase + Một số thuốc chống co giật như phenobarbital kìm hãm quá trình hydroxy hóa của vitamin D ở gan => dùng lâu gây còi xương. - Gđ 2 : 25(OH)D3 được vận chuyển đến thận. + Tại ty lạp thể của liên bào ống thận, nó chuyển thành 1α25-hydroxyvitaminD =25(OH)2D3 nhờ men 1, α-hydroxylase. Đây là chất chuyển hóa cuối cùng của vitamin D + Sự tổng hợp 1, 25 (OH)2 D3 ở thận được điều hoà một cách chặt chẽ theo cơ chế feedback tuỳ theo nhu cầu của cơ thể về Ca và P thông qua hormon PTH của tuyến cận giáp.",
