      "Thiếu ánh sáng mặt trời - Nhà ở chật chội, tối tăm. - Tập quán kiêng khem: trẻ nhỏ trong tháng đầu thường nằm phòng kín, trẻ lớn thì giữ trẻ trong nhà không cho tiếp xúc với ánh sáng mặt trời. Sự kiêng giữ quá mức của bà mẹ có thai và cho con bú. - Mặc nhiều quần áo về mùa đông. - Thời tiết: mùa đông, nơi nhiều sương mù, vùng công nghiệp nhiều khói bụi cản trở việc tiếp xúc với ánh nắng mặt trời của trẻ. 2. Chế độ ăn - Thiếu sữa mẹ nuôi con bằng sữa bò: tuy trong sữa bò hàm lượng canxi cao hơn trong sữa mẹ nhưng tỷ lệ Ca/P không cân đối nên khó hấp thu canxi. - Trẻ ăn nước cháo hoặc bột quá sớm và nhiều (vì trong bột có nhiều a.phytic gây cản trở hấp thu calci ở ruột). - Chế độ ăn thiếu dầu, mỡ (VTM D tan trong mỡ).",
